from pathlib import Path
base=Path('outputs/Шнек 1 — параметрическая модель').resolve();p=base/'index.html';s=p.read_text(encoding='utf-8')
s=s.replace("['incline','Угол наклона'","['incline','Угол к горизонтали'")
s=s.replace("const reach=68;","const reach=68;const portAngle=90-angle;")
