s=s.replace("setSchematicLine('portInArrow',inlet.x-reach-5,inlet.y,inlet.x-12,inlet.y);","setSchematicLine('portInArrow',inlet.x,inlet.y-reach-5,inlet.x,inlet.y-12);")
