s=s.replace("setSchematicLine('portOutArrow',outlet.x+12,outlet.y,outlet.x+reach+5,outlet.y);","setSchematicLine('portOutArrow',outlet.x,outlet.y+12,outlet.x,outlet.y+reach+5);")
s=s.replace("const r=30,mainArc=(point)=>angle<.001?'':`M ${point.x+r} ${point.y} A ${r} ${r} 0 0 0 ${point.x+r*co} ${point.y-r*si}`;", "const r=30,mainArc=(point,out=false)=>`M ${point.x+(out?-1:1)*r*co} ${point.y+(out?1:-1)*r*si} A ${r} ${r} 0 0 0 ${point.x} ${point.y+(out?1:-1)*r}`;")
s=s.replace("mainArc(outlet)","mainArc(outlet,true)")
s=s.replace("Math.max(60,inlet.x-reach/2),inlet.y-18,`ВХОД · ${fmt(angle)}°`", "inlet.x,inlet.y-reach-12,`ВХОД · ${fmt(portAngle)}°`")
s=s.replace("Math.min(720,outlet.x+reach/2),outlet.y-18,`ВЫХОД · ${fmt(angle)}°`", "outlet.x,outlet.y+reach+18,`ВЫХОД · ${fmt(portAngle)}°`")
