s=s.replace("$('dimPortAngle').textContent=fmt(v.incline)+'°'", "$('dimPortAngle').textContent=fmt(90-v.incline)+'°'")
s=s.replace("Допустимый ввод: 0–20°. Текущие 55° нужно изменить перед применением.","Допустимый ввод: 0–20°. Геометрия этой специальной сборки проверяется отдельно.")
s=s.replace("Углы свыше 20° относятся к специальному проекту; 55° сохранены по заданию.","Угол измеряется от горизонтали. По заданию требуется 55°; фактический угол CAD показан в контроле сборки.")
s=s.replace('<div class="section-head" id="gost">','<div class="note warning" style="margin-top:12px"><h3>Задание и фактическая геометрия</h3><p id="designAngleText">Загружается проверка угла…</p></div><div class="section-head" id="gost">')
s=s.replace('<section class="diagnostics"', '<div class="note" style="margin-top:12px"><h3>Проверка изменения параметров</h3><p id="parameterCheckText">Результаты тестов загружаются…</p></div><section class="diagnostics"',1)
s=s.replace("$('assemblyStatus').textContent=issues?'ЕСТЬ ОШИБКИ CAD':'CAD ПРОВЕРЕН';$('assemblyStatus').className=issues?'pill warn':'pill';", "$('assemblyStatus').textContent=issues?'ЕСТЬ ОШИБКИ CAD':data.design_angle_mismatch?'ТРЕБУЕТ ДОРАБОТКИ':'CAD ПРОВЕРЕН';$('assemblyStatus').className=issues||data.design_angle_mismatch?'pill warn':'pill';\n  $('designAngleText').textContent=`Задание: ${fmt(data.target_incline_deg)}° от горизонтали. В сохранённой CAD-модели: ${data.actual_incline_deg===null?'не проверено':fmt(data.actual_incline_deg)+'°'}. ${data.design_angle_mismatch?'Для целевого угла требуется переработка опоры и отверстия под верхний патрубок.':'Угол модели соответствует заданию.'}`;\n  const names={working_length:'Рабочая длина',tube_diameter:'Диаметр трубы',incline:'Угол по интерфейсу во время теста'};\n  $('parameterCheckText').textContent=(data.parameter_checks||[]).map(r=>`${names[r.parameter]}: ${fmt(r.before)} → ${fmt(r.tested)} → ${fmt(r.before)} — ${r.ok?'проверено без ошибок и пересечений':'вариант отклонён, сборка восстановлена'}`).join('. ')+'. Проверены отдельные варианты; полный диапазон размеров не подтверждён.';")
p.write_text(s,encoding='utf-8')
